from game_token import GameToken
from game_state import GameState
from drop_state import DropState
from game_logic_base import GameLogicBase

#
# DO NOT edit this file!
#

class GameLogicDummy(GameLogicBase):
    """
        This is a very simple (dummy) version of the GameLogic. It exists
        so that you can test your coordinator implementation.

        - It does not check the validity of a drop (except if column is inside
          the board).
        - It always places the token on the bottom-most row, overriding any
          token that previously occupied the position
        - The game is won by the player who has 4 tokens in the bottom-most
          row, regardless of their position 
        - It alternates between the red and yellow players.
    """

    ROWS = 6
    COLS = 7

    def __init__(self):
        super().__init__() # call constructor of the the base class
        self._board = [
            [' ',' ',' ',' ',' ',' ',' '], # row 0
            [' ',' ',' ',' ',' ',' ',' '], # row 1
            [' ',' ',' ',' ',' ',' ',' '], # row 2
            [' ',' ',' ',' ',' ',' ',' '], # row 3
            [' ',' ',' ',' ',' ',' ',' '], # row 4
            [' ',' ',' ',' ',' ',' ',' '], # row 5
            ]
        self._state = GameState.TURN_RED # red starts the game

    def get_state(self) -> GameState:
        # retruns a GameState enumeration constant
        return self._state


    def drop_token(self, player: GameToken, column: int) -> DropState:

        # is position valid? if not, return DropState.COLUMN_INVALID
        if not 0 <= column < self.COLS:
            print(f"ERROR: Position out of bounds: {column}.")
            return DropState.COLUMN_INVALID

        # always place the token in bottom-most row
        self._board[self.ROWS-1][column] = player

        # has the game been won already?
        if self._board[self.ROWS-1].count(GameToken.RED) >= 4:
            self._state = GameState.WON_RED
        elif self._board[self.ROWS-1].count(GameToken.YELLOW) >= 4:
            self._state = GameState.WON_YELLOW
        # if not, alternate player
        elif self._state == GameState.TURN_RED:
            self._state = GameState.TURN_YELLOW
        elif self._state == GameState.TURN_YELLOW:
            self._state = GameState.TURN_RED

        return DropState.DROP_OK
